#!/usr/bin/env bash
# Hardware-forwarded opposite-node paths for RoCEnante (generated by scripts/ring_mesh/plan.py). Idempotent.
set -euo pipefail
tc qdisc show dev enp1s0f0np0 | grep -q clsact || tc qdisc add dev enp1s0f0np0 clsact
tc qdisc show dev enp1s0f1np1 | grep -q clsact || tc qdisc add dev enp1s0f1np1 clsact
tc filter show dev enp1s0f1np1 ingress pref 49156 | grep -q flower || tc filter add dev enp1s0f1np1 ingress protocol 0x88b5 pref 49156 handle 49156 flower skip_sw src_mac 4c:bb:47:7d:4e:01 dst_mac 4c:bb:47:7e:0c:df action pedit ex munge eth type set 0x0800 pipe action pedit ex munge eth dst set 4c:bb:47:00:42:af pipe action mirred egress redirect dev enp1s0f0np0
tc -s filter show dev enp1s0f1np1 ingress pref 49156 | grep -q in_hw || { echo 'rule pref 49156 on enp1s0f1np1 is not in hardware'; exit 3; }
tc filter show dev enp1s0f0np0 ingress pref 49166 | grep -q flower || tc filter add dev enp1s0f0np0 ingress protocol 0x88b5 pref 49166 handle 49166 flower skip_sw src_mac 4c:bb:47:00:42:af dst_mac 4c:bb:47:7e:0c:de action pedit ex munge eth type set 0x0800 pipe action pedit ex munge eth dst set 4c:bb:47:7d:4e:01 pipe action mirred egress redirect dev enp1s0f1np1
tc -s filter show dev enp1s0f0np0 ingress pref 49166 | grep -q in_hw || { echo 'rule pref 49166 on enp1s0f0np0 is not in hardware'; exit 3; }
ip route show exact 10.250.6.3/32 | grep -q . || ip route add 10.250.6.3/32 via 10.250.5.4 dev enP2p1s0f0np0 src 10.250.5.2
ip route show exact 10.250.3.3/32 | grep -q . || ip route add 10.250.3.3/32 via 10.250.0.1 dev enp1s0f1np1 src 10.250.0.2
for d in roceP2p1s0f0 rocep1s0f1; do systemctl start dsv41-mesh-marker@$d; done
sleep 2; for d in roceP2p1s0f0 rocep1s0f1; do systemctl is-active --quiet dsv41-mesh-marker@$d || { echo marker $d not active; exit 4; }; done
echo mesh-up OK
